// ============================================
// 데이터 필터링 (재고 분석용)
// ============================================

const meta = $('쿼리 정제').first().json;
const rows = $input.first().json.values ?? [];
const [header, ...dataRows] = rows;

// 헤더 동적 매핑
const headerMap = Object.fromEntries(header.map((h, i) => [h, i]));
const idx = {
  카테고리: headerMap['카테고리'],
  상품명: headerMap['상품명'],
  옵션값: headerMap['옵션값'],
  주간구매개수: headerMap['주간구매개수'],
  월간구매개수: headerMap['월간구매개수'],
  잔여재고: headerMap['잔여재고']
};

// 헤더 누락 검증
const missingCols = Object.entries(idx)
  .filter(([_, v]) => v === undefined)
  .map(([k]) => k);
if (missingCols.length > 0) {
  throw new Error(`상품_적재 시트에서 다음 컬럼을 찾을 수 없습니다: ${missingCols.join(', ')}`);
}

// 상품 표시 헬퍼
const 상품표시 = (row) => {
  const 명 = row[idx.상품명] || '';
  const 옵 = row[idx.옵션값] || '';
  if (명 && 옵) return `${명} (${옵})`;
  return 명 || 옵 || '미상';
};

// 카테고리별 임계값 (운영 중 조정 가능)
const 카테고리별_임계값 = {
  '향료': 15,
  '공병': 10,
  '베이스,색소': 10,
  '기타 부자재': 10,
  '디퓨저': 5
};

// 기본 임계값 (매핑 안 된 카테고리용)
const DEFAULT_임계값 = 10;

// ---------- 1. 필터링 ----------
const filterRow = (row, 필터) => {
  // 카테고리 필터
  if (필터.카테고리 && 필터.카테고리.length > 0) {
    if (!필터.카테고리.includes(row[idx.카테고리])) return false;
  }

  // 상품 키워드 필터
  if (필터.상품키워드 && 필터.상품키워드.length > 0) {
    const 상품전체 = `${row[idx.상품명] || ''} ${row[idx.옵션값] || ''}`;
    const 매칭 = 필터.상품키워드.some(k => 상품전체.includes(k));
    if (!매칭) return false;
  }

  return true;
};

// ---------- 2. 재고 상태 판정 ----------
const 재고상태판정 = (row) => {
  const 카테고리 = row[idx.카테고리] || '미분류';
  const 잔여 = parseInt(row[idx.잔여재고]) || 0;
  const 월간 = parseInt(row[idx.월간구매개수]) || 0;

  const 임계값 = 카테고리별_임계값[카테고리] ?? DEFAULT_임계값;

  let 상태;
  if (잔여 === 0) 상태 = '품절';
  else if (잔여 <= 임계값) 상태 = '부족';
  else if (월간 > 0 && 잔여 < 월간) 상태 = '주의';  // 월간 소진 못 버팀
  else 상태 = '충분';

  return { 
    상태, 
    임계값, 
    예상소진일수: 월간 > 0 ? Math.floor((잔여 / 월간) * 30) : null 
  };
};

// ---------- 3. 메인 실행 ----------
const 필터링된 = dataRows.filter(row => filterRow(row, meta.필터 ?? {}));

// 각 행에 재고 상태 추가
const 재고데이터 = 필터링된.map(row => {
  const 판정 = 재고상태판정(row);
  return {
    카테고리: row[idx.카테고리],
    상품: 상품표시(row),
    주간구매: parseInt(row[idx.주간구매개수]) || 0,
    월간구매: parseInt(row[idx.월간구매개수]) || 0,
    잔여재고: parseInt(row[idx.잔여재고]) || 0,
    상태: 판정.상태,
    임계값: 판정.임계값,
    예상소진일수: 판정.예상소진일수
  };
});

// ---------- 4. 집계 ----------
const 결과 = {
  필터링상품수: 재고데이터.length
};

// 상태별 분류
const 부족품목 = 재고데이터.filter(r => r.상태 === '부족' || r.상태 === '품절');
const 주의품목 = 재고데이터.filter(r => r.상태 === '주의');
const 충분품목 = 재고데이터.filter(r => r.상태 === '충분');

// 카테고리별 집계
const 카테고리별 = {};
for (const r of 재고데이터) {
  const 카 = r.카테고리 || '미분류';
  if (!카테고리별[카]) {
    카테고리별[카] = { 총상품수: 0, 부족: 0, 주의: 0, 충분: 0, 품절: 0 };
  }
  카테고리별[카].총상품수 += 1;
  카테고리별[카][r.상태] = (카테고리별[카][r.상태] || 0) + 1;
}

결과.카테고리별_재고현황 = 카테고리별;
결과.부족품목 = 부족품목.sort((a, b) => a.잔여재고 - b.잔여재고);
결과.주의품목 = 주의품목.sort((a, b) => a.예상소진일수 - b.예상소진일수);

// 집계 스펙별 처리
for (const 스펙 of meta.집계 ?? []) {
  if (스펙.이름.includes('부족')) {
    결과[스펙.이름] = 부족품목.slice(0, 스펙.상위N || 10);
  } else if (스펙.이름.includes('카테고리')) {
    결과[스펙.이름] = 카테고리별;
  } else if (스펙.이름.includes('소진')) {
    // 예상 소진 임박 순
    결과[스펙.이름] = 재고데이터
      .filter(r => r.예상소진일수 !== null)
      .sort((a, b) => a.예상소진일수 - b.예상소진일수)
      .slice(0, 스펙.상위N || 10);
  } else {
    // 기본: 전체 데이터 반환
    결과[스펙.이름] = 재고데이터.slice(0, 스펙.상위N || 20);
  }
}

// 전체 요약
결과.전체총계 = {
  총상품수: 재고데이터.length,
  품절: 재고데이터.filter(r => r.상태 === '품절').length,
  부족: 재고데이터.filter(r => r.상태 === '부족').length,
  주의: 재고데이터.filter(r => r.상태 === '주의').length,
  충분: 재고데이터.filter(r => r.상태 === '충분').length
};

// ---------- 5. 최종 반환 ----------
return [{
  json: {
    ...meta,
    data: JSON.stringify(결과),
    dataSize: JSON.stringify(결과).length
  }
}];

const meta = $('데이터 필터링').first().json;
const raw = $('Report').first().json.output;
let parsed;
try {
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  parsed = { 문서코드: 'RPT', 오류: 'JSON 파싱 실패' };
}
const 문서코드 = parsed.문서코드 ?? meta.문서코드;
const 카테고리 = parsed.카테고리 ?? meta.카테고리;
const 구분선 = '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n';
const requests = [];
let currentIndex = 1;

const append = (text) => {
  requests.push({
    insertText: {
      text,
      endOfSegmentLocation: { segmentId: '' }
    }
  });
  currentIndex += text.length;
};

const appendHeading2 = (text) => {
  const startIdx = currentIndex;
  append(text);
  requests.push({
    updateParagraphStyle: {
      range: { startIndex: startIdx, endIndex: startIdx + text.length - 1 },
      paragraphStyle: { namedStyleType: 'HEADING_4' },
      fields: 'namedStyleType'
    }
  });
};

// 헤더
append('AROMAFOREST\n');
append('\n');
append(`문서번호: ${meta.문서번호}\n`);
append(`생성일시: ${meta.생성일시}\n`);
append(`문서유형: ${문서코드 === 'RPT' ? '데이터분석' : '인사이트'} | 카테고리: ${카테고리}\n`);
append('\n');
append(구분선);

// AROMAFOREST 폰트 스타일
requests.push({
  updateTextStyle: {
    range: { startIndex: 1, endIndex: 13 },
    textStyle: { fontSize: { magnitude: 20, unit: 'PT' } },
    fields: 'fontSize'
  }
});

if (문서코드 === 'RPT') {
  // 01. 요약
  appendHeading2('01. 요약\n');
  for (const item of parsed.요약 ?? []) {
    append(`  ${item.키}: ${item.값}\n`);
  }

  // 02. 상세 데이터
  appendHeading2('02. 상세 데이터\n');

  // 🆕 동적으로 '상세데이터*' 키 모두 수집
  const tables = Object.keys(parsed)
    .filter(k => k.startsWith('상세데이터'))
    .sort()
    .map(k => parsed[k])
    .filter(Boolean);

  for (const table of tables) {
    append(`\n${table.제목}\n`);
    requests.push({
      insertTable: {
        rows: table.행들.length + 1,
        columns: table.컬럼.length,
        endOfSegmentLocation: { segmentId: '' }
      }
    });
    append('\n');
  }

  // 03. 인사이트 (표 이후라 index 추적 없이 삽입만)
  if (parsed.인사이트?.length > 0) {
    requests.push({ insertText: { text: '03. 인사이트\n', endOfSegmentLocation: { segmentId: '' } } });
    for (const item of parsed.인사이트) {
      requests.push({ insertText: { text: `  • ${item}\n`, endOfSegmentLocation: { segmentId: '' } } });
    }
  }

  requests.push({ insertText: { text: `${parsed.합계 ?? ''}\n`, endOfSegmentLocation: { segmentId: '' } } });
  requests.push({ insertText: { text: 구분선, endOfSegmentLocation: { segmentId: '' } } });
} else {
  appendHeading2('01. 핵심 요약\n');
  append(`  ${parsed.핵심요약 ?? ''}\n`);
  appendHeading2('02. 분석 근거\n');
  for (const item of parsed.분석근거 ?? []) {
    append(`  • ${item}\n`);
  }
  appendHeading2('03. 참고 사항\n');
  for (const item of parsed.참고사항 ?? []) {
    append(`  • ${item}\n`);
  }
}

requests.push({ insertText: { text: '생성: 아로마포레스트 AI 분석 시스템\n', endOfSegmentLocation: { segmentId: '' } } });

const fullBody = JSON.stringify({ requests });
return [{
  json: {
    fullBody,
    parsedData: JSON.stringify(parsed),
    문서번호: meta.문서번호,
    문서코드,
    카테고리
  }
}];

// 파싱 AI 출력 정제
const raw = $input.first().json.output;
let query;
try {
  const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
  query = JSON.parse(cleaned);
} catch(e) {
  query = {
    문서코드: 'RPT',
    카테고리: '매출',
    필터: { 점주: null, 기간시작: null, 기간종료: null, 상품키워드: null },
    집계: [],
    비교: { 전월대비: false, 전년동월대비: false },
    오류: 'AI 출력 파싱 실패: ' + e.message
  };
}

// 문서 메타 생성
const now = new Date();
const 생성일시 = now.toISOString().slice(0, 16).replace('T', ' ');
const dateStr = now.toISOString().slice(0, 10).replace(/-/g, '');
const timeStr = now.toTimeString().slice(0, 8).replace(/:/g, '');  // HHmmss
const 문서번호 = `${query.문서코드}-${dateStr}-${timeStr}`;

// 원본 질문 가져오기 (Chat Trigger 노드 이름 확인 필요)
const question = $('When Executed by Another Workflow').first().json.original_query ?? '';

return [{
  json: {
    question,
    문서번호,
    생성일시,
    ...query
  }
}];

